CAT = "ea2Corporations"; SEG = "COR"
# C corporations and S corporations. Tax year 2025.
assert 0.8 * 60 == 48 and 45 < 48 and 45 < 50   # substantially disproportionate redemption
assert 4000 + 5000 - 8000 == 1000                # S basis after income, then distribution, before loss
